import { describe, test, expect, vi, beforeEach } from 'vitest';
import { renderHook } from '@testing-library/react';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { useCountryConfig } from './useCountryConfig';
import { COUNTRIES } from '../config/countries';

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: vi.fn(),
}));

const mockUseMultiSite = vi.mocked(useMultiSite);

function mockSite(siteId: string, localeId: string): void {
  mockUseMultiSite.mockReturnValue({ site: { id: siteId }, locale: { id: localeId } });
}

describe('useCountryConfig', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  test('returns AU config for ZimmermannAU + en', () => {
    mockSite('ZimmermannAU', 'en');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES.au);
    expect(result.current.checkoutOwner).toBe('sfcc');
    expect(result.current.globalEPricing).toBe(false);
  });

  test('returns UK config for ZimmermannUK + en-GB (not en-eu)', () => {
    mockSite('ZimmermannUK', 'en-GB');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES.uk);
    expect(result.current.sfccSiteId).toBe('ZimmermannUK');
  });

  test('returns en-eu config for ZimmermannEU + en-GB (not uk)', () => {
    mockSite('ZimmermannEU', 'en-GB');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['en-eu']);
    expect(result.current.sfccSiteId).toBe('ZimmermannEU');
  });

  test('returns fr-eu config for ZimmermannEU + fr', () => {
    mockSite('ZimmermannEU', 'fr');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['fr-eu']);
  });

  test('returns it-eu config for ZimmermannEU + it', () => {
    mockSite('ZimmermannEU', 'it');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['it-eu']);
  });

  test('returns es-eu config for ZimmermannEU + es', () => {
    mockSite('ZimmermannEU', 'es');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['es-eu']);
  });

  test('returns HK config with globalEPricing true for ZimmermannHK + en-HK', () => {
    mockSite('ZimmermannHK', 'en-HK');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES.hk);
    expect(result.current.checkoutOwner).toBe('global-e');
    expect(result.current.globalEPricing).toBe(true);
  });

  test('returns ME config for ZimmermannME + en-AE', () => {
    mockSite('ZimmermannME', 'en-AE');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['en-ae']);
    expect(result.current.checkoutOwner).toBe('global-e');
  });

  test('returns US international config for ZimmermannUSIntl + en-CA (not US domestic)', () => {
    mockSite('ZimmermannUSIntl', 'en-CA');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['en-ca']);
    expect(result.current.sfccSiteId).toBe('ZimmermannUSIntl');
    expect(result.current.checkoutOwner).toBe('global-e');
    expect(result.current.globalEPricing).toBe(true);
  });

  test('falls back to AU default for unrecognised site ID', () => {
    mockSite('RefArch', 'en-US');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES.au);
  });

  test('falls back to AU default when both args are undefined', () => {
    mockUseMultiSite.mockReturnValue({ site: undefined, locale: undefined });
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES.au);
  });
});

 * `@salesforce/retail-react-app/app/components/footer` through the overrides system and renders
 * `<Footer />` with **no props**, so there is no upstream container to own the data. This
 * wrapper is that seam, and the only place the Contentful fetch lives.
 *
 * HPC-034: fetches `footerConfig` entries via the Delivery API, then picks the entry scoped
 * to the current storefront's region (falls back to the global/unscoped entry once one
 * exists). Renders nothing while loading, on fetch failure, or when no entry resolves for
 * this region — no fallback to placeholder content once wired to live data, so a Contentful
 * outage doesn't silently ship stale placeholder copy to real shoppers. Note this puts a
 * fetch inside `components/`, which components.md reserves for containers; if that matters,
 * this should move into an `_app` override instead (Tier 2 shared shell — coordinate first).
 */
const FooterContainer = (props: Omit<FooterProps, 'data'>) => {
  // buildUrl + history.push, not useNavigation. useNavigation special-cases the home path
  // (`path === '/' ? '/' : updatedHref`), so navigate('/') pushes a bare '/' and skips the
  // site/locale prefix — on a prefixed storefront that drops the shopper onto the default
  // site. This is the exact pair base _app's onLogoClick uses, so both wordmarks resolve home
  // the same way on every storefront.
  //
  // useMultiSite ships untyped from the base SFCC package. site.id here is the resolved
  // SFCC site ID — confirmed against useCountryConfig.ts's identical client-side pattern
  // (`c.sfccSiteId === site?.id`), the existing precedent for this exact lookup.
  const {
    site,
    locale: siteLocale,
    buildUrl,
  } = useMultiSite() as {
    site: { id: string };
    locale?: { id: string };
    buildUrl: (path: string, siteRef?: string, localeRef?: string) => string;

