/*
 * Copyright (c) 2023, Salesforce, Inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

// Zimmermann storefronts — merged from two sources:
//   config/sites.generated.js — SCAPI-sourced locale/currency truth,
//     regenerate via `npm run sync:regional-config` (auto-generated, do not
//     hand-edit).
//   config/sites.overlay.js — hand-maintained routing data (URL alias,
//     sfccSiteId override) that Business Manager/SCAPI has no concept of.
// See .docs/prd/regional.md for routing rules; see
// .docs/planning/regionalConfigSyncPlan.md for why this is split this way.
/* eslint-disable @typescript-eslint/no-var-requires */
const generated = require('./sites.generated');
const overlay = require('./sites.overlay');

module.exports = overlay.map(({ id, sfccSiteId, locales }) => {
  const sourceId = sfccSiteId ?? id;
  const source = generated[sourceId];
  if (!source) {
    throw new Error(
      `config/sites.overlay.js references SFCC site '${sourceId}' (for PWA site '${id}') but ` +
        `config/sites.generated.js has no data for it. Run \`npm run sync:regional-config\`.`,
    );
  }
  return {
    id,
    ...(sfccSiteId ? { sfccSiteId } : {}),
    l10n: {
      supportedCurrencies: source.supportedCurrencies,
      defaultCurrency: source.defaultCurrency,
      // NOT source.defaultLocale — that's SCAPI's site-level default for the
      // real SFCC site, which can be a locale this PWA site doesn't even
      // support (e.g. BM's ZimmermannAU default is 'en-AU', but this PWA
      // site's overlay only lists 'en'; BM's ZimmermannEU default 'en-GB'
      // would wrongly apply to the EUfr/EUit/EUes PWA sites too, since all 4
      // share one real SFCC site). Every PWA site has exactly one locale in
      // its overlay, so that locale IS its default, full stop.
      defaultLocale: locales[0].id,
      supportedLocales: locales.map(({ id: localeId, alias }) => {
        const match = source.supportedLocales.find((l) => l.id === localeId);
        if (!match) {
          throw new Error(
            `config/sites.overlay.js declares locale '${localeId}' for site '${id}' but SFCC site ` +
              `'${sourceId}' does not support it per the latest sync. Run \`npm run sync:regional-config\` ` +
              `or check Business Manager.`,
          );
        }
        return { id: localeId, ...(alias ? { alias } : {}), preferredCurrency: match.preferredCurrency };
      }),
    },
  };
});

/*
 * Copyright (c) 2023, Salesforce, Inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

// Hand-maintained routing overlay — the half of config/sites.js's data that
// Business Manager / SCAPI has no concept of: URL aliases and the
// sfccSiteId override used when multiple PWA sites share one real SFCC site
// (EU domestic's 4-locale split). Locale/currency truth instead comes from
// config/sites.generated.js (regenerate via `npm run sync:regional-config`).
// See config/sites.js for how the two are merged.
//
// When adding a country/locale:
//   1. Add an entry here (id, optional sfccSiteId, locales[].alias).
//   2. Run `npm run sync:regional-config` — this regenerates
//      sites.generated.js, countries.generated.ts, and
//      contentfulMapping.generated.ts from Business Manager in one pass (the
//      site must already exist in BM). Do NOT hand-edit locale/currency data
//      in countries.ts or contentfulMapping.ts — it's derived now.
//   3. Add the new slug's business-logic entry to COUNTRY_OVERLAY in
//      overrides/app/config/countries.ts (shippingCountry, checkoutOwner,
//      globalEPricing, boutiqueRegion) — that part is still hand-maintained,
//      since Business Manager has no concept of it.
//   4. If it needs e2e coverage, add it to e2e/fixtures/site.overlay.js too.
//   5. Ensure a compiled translation exists in
//      overrides/app/static/translations/compiled/.
module.exports = [
  // AU — root (no prefix), x-default hreflang, gated to AU/Oceania IPs
  { id: 'ZimmermannAU', locales: [{ id: 'en' }] },
  // US domestic — /us/ via SFCC
  { id: 'ZimmermannUS', locales: [{ id: 'en-US', alias: 'us' }] },
  // US international — /en-ca/ — Global-e checkout (Canada + all other Americas)
  { id: 'ZimmermannUSIntl', locales: [{ id: 'en-CA', alias: 'en-ca' }] },
  // UK — /uk/ — SFCC checkout
  { id: 'ZimmermannUK', locales: [{ id: 'en-GB', alias: 'uk' }] },
  // EU domestic — four single-locale PWA sites, all backed by SFCC ZimmermannEU
  { id: 'ZimmermannEUen', sfccSiteId: 'ZimmermannEU', locales: [{ id: 'en-GB', alias: 'en-eu' }] },
  { id: 'ZimmermannEUfr', sfccSiteId: 'ZimmermannEU', locales: [{ id: 'fr', alias: 'fr-eu' }] },
  { id: 'ZimmermannEUit', sfccSiteId: 'ZimmermannEU', locales: [{ id: 'it', alias: 'it-eu' }] },
  { id: 'ZimmermannEUes', sfccSiteId: 'ZimmermannEU', locales: [{ id: 'es', alias: 'es-eu' }] },
  // EU international — /en-ch/ — Global-e checkout (non-EU Europe + Africa + ROW)
  { id: 'ZimmermannEUIntl', locales: [{ id: 'en-CH', alias: 'en-ch' }] },
  // HK — /hk/ — Global-e checkout (Asia-Pacific)
  { id: 'ZimmermannHK', locales: [{ id: 'en-HK', alias: 'hk' }] },
  // ME — /en-ae/ — Global-e checkout (Middle East)
  { id: 'ZimmermannME', locales: [{ id: 'en-AE', alias: 'en-ae' }] },
];

  hk: { shippingCountry: 'HK', checkoutOwner: 'global-e', globalEPricing: true, boutiqueRegion: 'hong-kong' },
  'en-ae': { shippingCountry: 'AE', checkoutOwner: 'global-e', globalEPricing: true, boutiqueRegion: 'middle-east' },
};

/**
 * Keyed by urlSlug for O(1) lookup in routing/middleware.
 * AU is the exception: it has no URL prefix (root domain). Its key is 'au'
 * but urlSlug is '' — routing falls back to DEFAULT_COUNTRY_SLUG when no
 * prefix is detected.
 */
// Fail loud, not silent, if BM/the sync script produced a slug with no
// matching business-logic overlay — that means someone added a site to
// config/sites.overlay.js and ran `npm run sync:regional-config` without
// adding the corresponding COUNTRY_OVERLAY entry above. The reverse case
// (an overlay entry with no generated data yet, e.g. 'en-ca' pending the
// US-split site ID) is intentional and handled by the filter below instead.
const missingOverlays = Object.keys(GENERATED_COUNTRIES).filter((slug) => !(slug in COUNTRY_OVERLAY));
if (missingOverlays.length) {
  throw new Error(
    `countries.ts: config/sites.overlay.js has a site for slug(s) '${missingOverlays.join(', ')}' with no ` +
      `matching COUNTRY_OVERLAY entry — add shippingCountry/checkoutOwner/globalEPricing/boutiqueRegion for it.`,
  );
}

export const COUNTRIES: Record<string, CountryConfig> = Object.fromEntries(
  Object.entries(COUNTRY_OVERLAY)
    .filter(([slug]) => slug in GENERATED_COUNTRIES)
    .map(([slug, overlay]) => [
      slug,
      {
        urlSlug: slug === 'au' ? '' : slug,
        ...(GENERATED_COUNTRIES as Record<string, { sfccSiteId: string; locale: string; currency: string }>)[slug],
        ...overlay,
      },
    ]),
);

/** Fallback when no URL slug is present or IP detection fails. */
export const DEFAULT_COUNTRY_SLUG = 'au';

/*
 * Copyright (c) 2021, salesforce.com, inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

import {useCallback, useContext} from 'react'
import {MultiSiteContext} from '@salesforce/retail-react-app/app/contexts'

/**
 * Custom React hook to get the function that returns usefule multi-site values, the site, the locale and
 * the function used to build URLs following the App configuration.
 * @returns {{site, locale, buildUrl: (function(*, *, *): *)}}
 */
const useMultiSite = () => {
    const context = useContext(MultiSiteContext)
    if (context === undefined) {
        throw new Error('useMultiSite must be used within MultiSiteProvider')
    }
    const {buildUrl: originalFn, site, locale} = context

    const buildUrl = useCallback(
        (path, siteRef, localeRef) => {
            return originalFn(
                path,
                siteRef ? siteRef : site?.alias || site?.id,
                localeRef ? localeRef : locale?.alias || locale?.id
            )
        },
        [originalFn, site, locale]
    )
    return {site, locale, buildUrl}
}

export default useMultiSite

