  test('returns it-eu config for ZimmermannEU + it', () => {
    mockSite('ZimmermannEU', 'it');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['it-eu']);
  });

  test('returns es-eu config for ZimmermannEU + es', () => {
    mockSite('ZimmermannEU', 'es');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['es-eu']);
  });

  test('returns HK config with globalEPricing true for ZimmermannHK + en-HK', () => {
    mockSite('ZimmermannHK', 'en-HK');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES.hk);
    expect(result.current.checkoutOwner).toBe('global-e');
    expect(result.current.globalEPricing).toBe(true);
  });

  test('returns ME config for ZimmermannME + en-AE', () => {
    mockSite('ZimmermannME', 'en-AE');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['en-ae']);
    expect(result.current.checkoutOwner).toBe('global-e');
  });

  test('returns US international config for ZimmermannUSIntl + en-CA (not US domestic)', () => {
    mockSite('ZimmermannUSIntl', 'en-CA');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['en-ca']);
    expect(result.current.sfccSiteId).toBe('ZimmermannUSIntl');
    expect(result.current.checkoutOwner).toBe('global-e');
    expect(result.current.globalEPricing).toBe(true);
  });

  test('falls back to AU default for unrecognised site ID', () => {
    mockSite('RefArch', 'en-US');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES.au);
  });

  test('falls back to AU default when both args are undefined', () => {
    mockUseMultiSite.mockReturnValue({ site: undefined, locale: undefined });
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES.au);
  });
});

