// entry per PWA site (keyed by e.g. 'ZimmermannEUfr' directly, not the shared SFCC
// site id), confirmed via a live query against that content type. This is a narrower
// claim than "site.id is generally the resolved SFCC site ID" — it is not, and must
// not be assumed correct elsewhere by analogy to this lookup.
const {
  site,
  locale: siteLocale,
  buildUrl,
} = useMultiSite() as {
  site: { id: string };
  locale?: { id: string };
  buildUrl: (path: string, siteRef?: string, localeRef?: string) => string;
};
const locale = siteLocale?.id ?? CONTENTFUL_FALLBACK_LOCALE;
const history = useHistory();
const { client } = useContentfulClient();
const [footerData, setFooterData] = useState<FooterConfigEntry | null>(null);

useEffect(() => {
  if (!client) return;
  let cancelled = false;

  // useContentfulClient types the client as ContentfulClientApi<any> for the Experiences
  // SDK's benefit — with `any` chain modifiers, EntriesQueries's `locale` field resolves out
  // of the type entirely (see useHeaderNav.ts's identical cast for the full explanation).
  (client as ContentfulClientApi<undefined>)
    .getEntries({ content_type: 'footerConfig', include: FOOTER_INCLUDE_DEPTH, locale })
    .then((response) => {
      if (cancelled) return;
      // The contentful SDK client is loosely typed (see useContentfulClient.ts) —
      // FooterConfigEntry mirrors the exact nested-resolved shape `include: 3` produces
      // for this content model.
      const configs = response.items as unknown as FooterConfigEntry[];
      const resolved = pickMostSpecificByRegion<FooterConfigEntry>(configs, site.id);
      setFooterData(resolved ? scopeToRegion(resolved, site.id) : null);
    })
    .catch(() => {
      if (!cancelled) setFooterData(null);
    });

