#!/usr/bin/env node
/**
 * Seed the 11 canonical `region` entries into one target environment.
 *
 * Environment Templates (buildTemplate.js / installTemplate.mjs) cover content-TYPE
 * schema only — entries are a separate concern and have to be seeded per environment
 * after that environment's `region` content type exists (i.e. after installTemplate.mjs
 * has run against it).
 *
 * Idempotent — uses deterministic entry IDs (`region-<siteId>`) so re-running is safe.
 *
 * Usage:
 *   npm run seed:contentful-regions -- --target dev
 */

import { checkEnv, createClient, log } from './_shared.mjs';

const args = process.argv.slice(2);
const getArg = (flag) => {
  const i = args.indexOf(flag);
  return i !== -1 ? args[i + 1] : null;
};

const TARGET = getArg('--target');

if (!TARGET) {
  log.error('--target <environmentId> is required.');
  console.error('  Example: npm run seed:contentful-regions -- --target dev\n');
  process.exit(1);
}

// Space default locale — matches DEFAULT_LOCALE in overrides/app/config/contentfulMapping.ts.
const DEFAULT_LOCALE = 'en';

// Source: overrides/app/config/contentfulMapping.generated.ts's SITE_LOCALES keys,
// copied 2026-08-23. Re-check that file if this list needs to change — it's
// autogenerated from live SFCC site config via `npm run sync:regional-config` and this
// static copy can drift from it.
const REGION_SEEDS = [
  { siteId: 'ZimmermannAU', label: 'Australia', locale: 'en' },
  { siteId: 'ZimmermannUS', label: 'US Domestic', locale: 'en-US' },
  { siteId: 'ZimmermannUSIntl', label: 'US International', locale: 'en-CA' },
  { siteId: 'ZimmermannUK', label: 'United Kingdom', locale: 'en-GB' },
  { siteId: 'ZimmermannEUen', label: 'Europe (English)', locale: 'en-GB' },
  { siteId: 'ZimmermannEUfr', label: 'Europe (French)', locale: 'fr' },
  { siteId: 'ZimmermannEUit', label: 'Europe (Italian)', locale: 'it' },
  { siteId: 'ZimmermannEUes', label: 'Europe (Spanish)', locale: 'es' },
  { siteId: 'ZimmermannEUIntl', label: 'Europe International', locale: 'en-CH' },
  { siteId: 'ZimmermannHK', label: 'Hong Kong', locale: 'en-HK' },
  { siteId: 'ZimmermannME', label: 'Middle East', locale: 'en-AE' },
];

async function upsertEntry(client, environmentId, contentTypeId, entryId, fields) {
  const localizedFields = Object.fromEntries(
    Object.entries(fields).map(([fieldId, value]) => [fieldId, { [DEFAULT_LOCALE]: value }]),
  );

  let exists = true;
  try {
    await client.entry.get({ environmentId, entryId });
  } catch (err) {
    if (err.name !== 'NotFound') throw err;
    exists = false;
  }

  if (exists) {
    log.skip(`region-${fields.siteId} already exists`);
    return;
  }

  const entry = await client.entry.createWithId({ environmentId, entryId, contentTypeId }, { fields: localizedFields });
  await client.entry.publish({ environmentId, entryId }, entry);
  log.success(`Seeded region-${fields.siteId}`);
}

async function main() {
  checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);

  const client = createClient();

  log.section(`Seed regions → '${TARGET}'`);

  for (const seed of REGION_SEEDS) {
    await upsertEntry(client, TARGET, 'region', `region-${seed.siteId}`, seed);
  }

  console.log(`\n  ✅  Region entries up to date in '${TARGET}'.\n`);
}

main().catch((err) => {
  log.error(err.message ?? err);
  process.exit(1);
});

/** @type {import('../buildTemplate').ContentTypeDefinition} */
module.exports = {
  id: 'region',
  name: 'Region',
  displayField: 'label',
  description:
    'One entry per SFCC storefront/region — the canonical, referenceable region entity. ' +
    'Any content type needing region-scoping (links, footer config, etc.) references this ' +
    'via a `regions` field, rather than duplicating a hardcoded site-ID list.',
  fields: [
    {
      id: 'siteId',
      name: 'Site ID',
      type: 'Symbol',
      required: true,
      localized: false,
      validations: [{ unique: true }],
      // Canonical join key — matches an SFCC site ID from
      // overrides/app/config/contentfulMapping.generated.ts's SITE_LOCALES keys.
    },
    {
      id: 'label',
      name: 'Label',
      type: 'Symbol',
      required: true,
      localized: false,
      // Editor-facing display name (e.g. "Australia"). Admin label, not shopper-facing
      // copy — not localized.
    },
    {
      id: 'locale',
      name: 'Locale',
      type: 'Symbol',
      required: false,
      localized: false,
      // Informational only, mirrors the site's primary locale (e.g. 'en'). Helps an
      // editor sanity-check they picked the right region when selecting a reference.
    },
  ],
};

